/* ─── TEAM ─── */
function TeamCard({ name, role, initials }) {
    const [hov, setHov] = useState(false);
    const palette = { President: R, "Vice President": Y, Secretary: R, Treasurer: Y, "Events Chair": R, Marketing: Y };
    const c = palette[role] || R;
    return (
        <div onMouseEnter={() => setHov(true)} onMouseLeave={() => setHov(false)} style={{
            background: W, border: `1.5px solid ${hov ? Y : "#EEE"}`,
            borderRadius: 24, padding: "2rem", textAlign: "center",
            transform: hov ? "translateY(-6px)" : "translateY(0)",
            boxShadow: hov ? `0 12px 32px ${Y}28` : "none",
            transition: "all 0.3s ease",
        }}>
            <div style={{ width: 72, height: 72, borderRadius: "50%", background: c === Y ? Y : R, border: `3px solid ${c === Y ? R : Y}`, margin: "0 auto 16px", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "\'Bebas Neue\', Impact, sans-serif", fontSize: 22, color: W }}>
                {initials}
            </div>
            <div style={{ fontFamily: "\'Bebas Neue\', Impact, sans-serif", fontSize: 18, color: DARK, letterSpacing: "0.04em", marginBottom: 4 }}>{name}</div>
            <div style={{ fontSize: 11, color: c === Y ? R : R, fontWeight: 700, letterSpacing: "0.14em", textTransform: "uppercase", marginBottom: 16 }}>{role}</div>
            <a href="#" style={{ display: "inline-block", background: "#F5F5F5", border: "1.5px solid #EEE", borderRadius: 100, padding: "6px 16px", fontSize: 11.5, color: "#888", textDecoration: "none", transition: "all 0.2s" }}
               onMouseEnter={e => { e.target.style.background = Y; e.target.style.color = R; e.target.style.borderColor = Y; }}
               onMouseLeave={e => { e.target.style.background = "#F5F5F5"; e.target.style.color = "#888"; e.target.style.borderColor = "#EEE"; }}
            >LinkedIn →</a>
        </div>
    );
}

function Team() {
    return (
        <section id="team" style={{ padding: "7rem 5rem", maxWidth: 1200, margin: "0 auto", background: W }}>
            <FadeIn>
                <SL>The Team</SL>
                <h2 style={{ fontFamily: "\'Bebas Neue\', Impact, sans-serif", fontSize: "clamp(2.8rem, 5vw, 4.2rem)", color: DARK, lineHeight: 0.95, marginBottom: 12 }}>
                    Get To Know <span style={{ color: R }}>Us</span>
                </h2>
                <p style={{ fontSize: 14, color: "#888", maxWidth: 420, lineHeight: 1.7, marginBottom: 48 }}>The passionate students building ColorStack UCalgary — your people in tech at the University of Calgary.</p>
            </FadeIn>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16 }}>
                {TEAM.map((m, i) => (
                    <FadeIn key={m.role + i} delay={i * 0.08}><TeamCard {...m} /></FadeIn>
                ))}
                <FadeIn delay={0.5}>
                    <div style={{ border: "2px dashed #DDD", borderRadius: 24, padding: "2rem", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", minHeight: 200, color: "#BBB", textAlign: "center" }}>
                        <div style={{ fontSize: 22, marginBottom: 8 }}>+</div>
                        <div style={{ fontSize: 13 }}>More roles<br/>coming soon</div>
                    </div>
                </FadeIn>
            </div>
        </section>
    );
}

/* ─── FOOTER ─── */
function Footer() {
    return (
        <footer style={{ background: DARK, borderTop: `4px solid ${Y}`, padding: "3rem 5rem", display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 20 }}>
            <div>
                <div style={{ fontFamily: "\'Bebas Neue\', Impact, sans-serif", fontSize: 17, color: Y, letterSpacing: "0.08em" }}>ColorStack UCalgary</div>
                <div style={{ fontSize: 11, color: "rgba(255,255,255,0.3)", marginTop: 4 }}>Part of ColorStack National · colorstack.org</div>
            </div>
            <div style={{ display: "flex", gap: 24, flexWrap: "wrap" }}>
                {[...NAV_LINKS, { label: "Contact", href: "mailto:colorstackucalgary@gmail.com" }].map(l => (
                    <a key={l.label} href={l.href} style={{ fontSize: 13, color: "rgba(255,255,255,0.4)", textDecoration: "none", transition: "color 0.2s" }}
                       onMouseEnter={e => e.target.style.color = Y}
                       onMouseLeave={e => e.target.style.color = "rgba(255,255,255,0.4)"}
                    >{l.label}</a>
                ))}
            </div>
            <div style={{ display: "flex", gap: 12 }}>
                {SOCIAL_LINKS.map(s => (
                    <a key={s.name} href={s.href} target="_blank" rel="noreferrer" style={{ fontSize: 12, color: "rgba(255,255,255,0.35)", textDecoration: "none", transition: "color 0.2s" }}
                       onMouseEnter={e => e.target.style.color = Y}
                       onMouseLeave={e => e.target.style.color = "rgba(255,255,255,0.35)"}
                    >{s.name}</a>
                ))}
            </div>
            <div style={{ fontSize: 11, color: "rgba(255,255,255,0.2)" }}>© 2025 ColorStack UCalgary</div>
        </footer>
    );
}

/* ─── ROOT ─── */
export default function App() {
    return (
        <div style={{ background: W, minHeight: "100vh" }}>
            <Nav />
            <Hero />
            <Ticker />
            <About />
            <Offers />
            <Events />
            <Resources />
            <JoinBanner />
            <Team />
            <Footer />
        </div>
    );
}